module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg [7:0] data_in = 0;
  reg valid_a = 0;
  reg ready_b = 1;
  wire ready_a;
  wire valid_b;
  wire [9:0] data_out;

  TopModule dut(
    .clk(clk), .rst_n(rst_n), .data_in(data_in), .valid_a(valid_a), .ready_b(ready_b),
    .ready_a(ready_a), .valid_b(valid_b), .data_out(data_out)
  );

  always #5 clk = ~clk;

  task automatic drive(input [7:0] value, input integer hold_cycles);
    begin
      @(negedge clk);
      data_in = value;
      valid_a = 1;
      repeat (hold_cycles) @(negedge clk);
      @(negedge clk);
      valid_a = 0;
    end
  endtask

  always @(posedge clk) begin
    "'$display("t=%0t cnt=%0d va=%0b ra=%0b di=%0d vb=%0b rb=%0b do=%0d", $time, dut.data_cnt, valid_a, ready_a, data_in, valid_b, ready_b, data_out);
  end

  initial begin
    repeat (2) @(negedge clk);
    rst_n = 1;
    drive(1,0); drive(2,0); drive(3,0); drive(4,0);
    // stall output for two cycles when first result appears
    wait(valid_b == 1);
    @(negedge clk); ready_b = 0;
    repeat (2) @(negedge clk);
    ready_b = 1;
    drive(10,0); drive(20,0); drive(30,0); drive(40,0);
    repeat (8) @(negedge clk);
    $finish;
  end
endmodule
